  let m = f.querySelector(':scope > .fld-err');
  if (!m) { m = document.createElement('span'); m.className = 'fld-err'; m.id = id; m.setAttribute('role', 'alert'); f.append(m); }
  m.innerHTML = `${ic('warn')}<span>${esc(msg)}</span>`;
