    if (drawn) { S.inv = iv.invocations; S.top = tp; S.met = mt; S.links = ln ? ln.links : S.links; readAt.home = Date.now(); }
    S.ses = ss ? ss.sessions : []; S.teams = tm ? tm.teams : []; S.reqs = rq ? rq.requests : []; S.lock = lk; S.fbc = fc || S.fbc; S.dec = dc ? dc.decisions : S.dec || []; S.dirU = drp ? drp.count : S.dirU || 0; S.dirS = drp ? drp.suggestions || 0 : S.dirS || 0;
