  /* Each member's own branch; a checkpoint without checkout_branch (before 16 Nov) means checkout/<id>. */
  const cb = cp.checkout_branch || `checkout/${c.id}`;
  if (cp.checkout_head) k.push(kv('Not approved yet', `<span title="${esc(cb)}">${esc(midTrunc(cb, 30))}</span>`, { id: true }), kv('Its head', esc(coSha(cp.checkout_head)), { id: true }));
  if (h.report) k.push(kv('Left behind', esc(`${r.worktrees_left ? plural(r.worktrees_left, 'worktree') : 'No worktree'} · ${r.clean ? 'tree clean' : 'uncommitted work'}`)));
