function coFormWire(t, c, o, f, id, cP, re) {
  const draw = () => { $('#coForm').innerHTML = coFormHtml(t, c, o, f); $('#coSum').innerHTML = coSumHtml(t, c, f); tipIcons($('#coForm')); coFormWire(t, c, o, f, id, cP, re); };
  $$('[data-co-tg]').forEach((b) => (b.onclick = () => { f.target = b.dataset.coTg; if (f.target !== 'same_user') f.rotate = true; draw(); $(`[data-co-tg="${f.target}"]`)?.focus(); }));
  $$('[data-co-rot]').forEach((b) => (b.onclick = () => { f.rotate = b.dataset.coRot === '1'; draw(); $(`[data-co-rot="${f.rotate ? 1 : 0}"]`)?.focus(); }));
  if ($('#coPc')) $('#coPc').onchange = (e) => { f.pc = e.target.value; draw(); $('#coPc').focus(); };
  if ($('#coAccept')) $('#coAccept').onchange = (e) => { f.accept = e.target.checked; };
  $$('[data-co-ag]').forEach((r) => (r.onchange = (e) => { const k = e.target.dataset.coF, a = f.agents[r.dataset.coAg]; if (!k || !a) return;
    a[k] = e.target.value.trim(); if (k === 'provider') { a.model = ''; draw(); $(`[data-co-ag="${CSS.escape(r.dataset.coAg)}"] [data-co-f="provider"]`)?.focus(); } }));
  $$('[data-co-ag] [data-co-f="model"]').forEach((x) => (x.oninput = () => { f.agents[x.closest('[data-co-ag]').dataset.coAg].model = x.value.trim(); }));
  const go = () => run(async () => {
    const body = { target: f.target, rotate_agent_keys: f.target === 'same_user' ? f.rotate : true,
      agents: Object.fromEntries(Object.entries(f.agents).map(([a, x]) => [a, { provider: x.provider, model: x.model || null, permissions: x.permissions }])) };
    if (f.target === 'other_pc') { if (f.pc) body.machine_id = f.pc; else { toast('Add the PC with the connector first', true); return; } }
    if ((o.unmerged_work_on_source || []).length && f.target !== 'same_user') { if (!f.accept) { const x = $('#coAccept'); if (x) { x.closest('.fld').scrollIntoView({ block: 'center' }); fieldErr(x, `Tick this box first: the unmerged work stays on ${coPc(c.source_machine_id)} and does not move to the target.`); } return; } body.accept_unmerged_work = true; }
    let r;
    try { r = await post(cP + '/render', body); }
    catch (e) { if (e.code === 'restore_unavailable') { CO.unavail[c.id] = true; draw(); $('.co-warn')?.scrollIntoView({ block: 'nearest' }); return; } throw e; }
    delete CO.unavail[c.id]; CO.edit[c.id] = false;
    CO.prompt[c.id] = { text: r.prompt.text, expires_at: r.prompt.expires_at, push: r.push_list };
    toast('Prompt ready · copy it now'); await re();
  });
  if (c.status === 'rendered') arm($('#coRender'), go, 'Revoke the old prompt'); else $('#coRender').onclick = go;
  if ($('#coKeep')) $('#coKeep').onclick = () => { CO.edit[c.id] = false; openD('tco', id, true); };
}
function coCancel(c, cP, re) {
  const restoring = c.status === 'restoring';
  fbSheet({ title: 'Cancel checkout', tone: 'bad', label: 'Cancel checkout', dismiss: 'Keep checkout',
    fields: vnote(restoring ? 'Agents already on the target stay there. Keys not yet confirmed are revoked. The team stays paused unless you lift the pause.' : 'Handouts are removed, keys not yet collected are revoked, old logins come back and the team resumes. Merges already made stay.')
      + (restoring ? '<label class="co-chk"><input type="checkbox" id="coForce"><span>Lift the team pause too</span></label>' : '') + fbArea('coNote', 'Note for the audit (optional)', 500, 2),
    onGo: async (sh) => { await post(cP + '/cancel', { note: fbVal(sh, 'coNote') || null, ...(restoring ? { force: $('#coForce', sh).checked } : {}) }); toast('Checkout cancelled'); re(); } });
}
/* The team page: a Checkout card while one is open (filled after the page draws, from the last answer meanwhile), and its menu entry. */
