  const doStatus = () => run(async () => {
    const r = await post(`/users/${encodeURIComponent(id)}/${on ? 'disable' : 'enable'}`);
    const own = (r && r.owned_agents) || [];
    toast(!on ? 'User enabled' : own.length ? `User disabled. They own ${own.length === 1 ? own[0].label : `${own.length} agents (${own.slice(0, 3).map((a) => a.label).join(', ')}${own.length > 3 ? ', …' : ''})`}: hand them on under Owns agents` : 'User disabled');
    re();
  });
