// ==== Admin settings and smaller gaps ====
/* Console screens for hub features that needed the raw API (docs/dashboard-ux.md): the onboarding capability of app keys,
   Mark all as reviewed and agents' reports in Directives, Projects with the Blueprint limits, older revisions of a Blueprint
   item, renaming and moving an agent, a team's past recruit requests and start-overs, and permission templates.
   The screens register below (ADM_VIEWS, ADM_ROUTES, ADM_NAV); the other screens call the adm* helpers. */
const ADM = { rep: null, repOpen: false, hist: null };
const admNum = (n) => Number(n).toLocaleString('en');

/* Keys: the onboarding capability of an app key (docs/onboarding.md). Off asks once more; on is one click. */
const admOnbMeta = (k) => (k.kind === 'app_key' && k.onboarding_enabled_at ? 'Onboarding on' : '');
const admOnbKv = (k, dead) => (k.kind !== 'app_key' ? '' : kv('Onboarding', `<span class="kv-trunc">${k.onboarding_enabled_at ? esc('On since ' + dt(k.onboarding_enabled_at)) : 'Off'}</span>${info('Lets the PC file team requests and pick up their keys. Nothing else.')}${dead ? '' : switchBtn('Onboarding capability', !!k.onboarding_enabled_at, 'id="kOnb"')}`));
function admOnbBind(k, act) {
  const b = $('#kOnb'); if (!b) return;
  const p = '/keys/' + encodeURIComponent(k.id) + '/onboarding';
  b.onclick = (e) => {
    if (!k.onboarding_enabled_at) return act(() => api(p, 'PUT'), 'Onboarding on: the PC can file team requests');
    fbSheet({ title: 'Turn off onboarding?', anchor: e.currentTarget, label: 'Turn off', tone: 'bad', fields: `<p>${esc(keyName(k))} can no longer file team requests or pick up keys. Its agents keep working.</p>`,
      onGo: () => { act(() => api(p, 'DELETE'), 'Onboarding off'); } });
  };
}

/* Directives: Mark all as reviewed (asks with the count), and the reports agents filed, shown only while there are any. */
const admRevAllBtn = () => (S.dirU ? `<button type="button" class="btn sm" id="admRevAll">${ic('check')}Mark all as reviewed</button>` : '');
const admRevAllMenu = () => (S.dirU ? [{ label: 'Mark all as reviewed', icon: 'check', fn: () => admRevAll(null) }] : []);
function admRevAll(anchor) {
  run(async () => {
    const n = (await api('/directives/unreviewed-count')).count;
    if (!n) { toast('Nothing left to review'); return reopen(); }
    fbSheet({ title: `Mark ${plural(n, 'directive')} as reviewed?`, anchor, label: `Mark ${n} reviewed`, fields: '<p>Each rule stays as agents registered it, category included.</p>',
      onGo: async () => { const r = await post('/directives/review-all', {}); toast(`Marked ${plural(r.reviewed, 'directive')} as reviewed`); await refresh(); reopen(); } });
  });
}
const ADM_REP_ST = { open: ['Waiting', 'warn'], adopted: ['Adopted', 'ok'], known: ['Already a rule', 'ok'], retired: ['Retired', 'idle'] };
function admRepHtml() {
  // Shown only while a report waits; the decided ones fold under it (each opens the directive it became).
  const L = ADM.rep || [], open = L.filter((r) => r.status === 'open'), done = L.filter((r) => r.status !== 'open');
  if (!open.length) return '';
  const rowOf = (r) => {
    const dec = r.status !== 'open' && r.directive_id, st = ADM_REP_ST[r.status] || [cap(r.status), 'idle'];
    return row({ title: r.title, meta: [r.agent_label, r.team_label, r.source, `${ago(r.decided_at || r.created_at)} ago`].filter(Boolean).join(' · '),
      trail: r.status === 'open' ? `<button type="button" class="btn sm" data-admrep-ret="${esc(r.id)}">Retire</button><button type="button" class="btn sm" data-admrep-ad="${esc(r.id)}">${ic('check')}Adopt</button>` : pill(st[0], st[1]),
      chev: !!dec, attrs: dec ? { 'data-dir': r.directive_id, title: `Open the directive made from ${r.title}` } : {} });
  };
  return `<div class="pcard adm-rep">${kd('Suggestions from agents', `<span class="meta">${open.length ? `${open.length} waiting · ` : ''}${done.length} decided</span>`)}${open.map(rowOf).join('')}`
    + (done.length ? row({ one: true, group: true, expanded: ADM.repOpen, title: ADM.repOpen ? 'Hide decided reports' : `Show ${plural(done.length, 'decided report')}`, attrs: { 'data-admrep-more': '1' } }) + (ADM.repOpen ? done.map(rowOf).join('') : '') : '') + '</div>';
}
function admRepBind() {
  const box = $('#admRep'); if (!box) return;
  const draw = () => { box.innerHTML = admRepHtml(); tipIcons(box); };
  box.onclick = (e) => {
    const b = e.target.closest('button'); if (!b) return;
    if (b.matches('[data-admrep-more]')) { ADM.repOpen = !ADM.repOpen; draw(); $('[data-admrep-more]', box)?.focus(); return; }
    const r = (ADM.rep || []).find((x) => x.id === (b.dataset.admrepAd || b.dataset.admrepRet)); if (!r) return;
    const rp = '/directive-reports/' + encodeURIComponent(r.id);
    if (b.dataset.admrepRet) fbSheet({ title: 'Retire this rule?', anchor: b, label: 'Retire', tone: 'bad', fields: fbArea('admRepN', `Why (optional, ${r.agent_label} sees it)`, 500, 2),
      onGo: async (sh) => { await post(rp + '/retire', { note: fbVal(sh, 'admRepN') || null }); toast(`Retired; ${r.agent_label} is told to stop`); ADM.rep = null; reopen(); } });
    else fbSheet({ title: 'Adopt as a directive', label: 'Adopt', fields: `<label class="fld"><span class="vlabel">Title</span><input class="inp" id="admRepT" maxlength="120" value="${esc(r.title)}"></label>`
      + `<label class="fld"><span class="vlabel">Text</span><textarea class="inp" id="admRepB" rows="4" maxlength="20000">${esc(r.text || r.summary || '')}</textarea></label><p class="hint">${r.team_label ? `It becomes a directive for ${esc(r.team_label)}${r.category ? `, filed under ${esc(DIR_CAT_LABEL[r.category] || r.category)}` : ''}. The same suggestion from other members of that team closes with it.` : `It applies to ${esc(r.agent_label)} first; widen it after.`}</p>`,
    onGo: async (sh) => {
      const t = fbVal(sh, 'admRepT'), body = fbVal(sh, 'admRepB');
      if (!t) return ['Give it a title.', 'admRepT'];
      if (!body) return 'Add the rule\'s text: the agent did not send it.';
      const x = await post(rp + '/adopt', { title: t, body }); toast(x.merged ? `Adopted; ${r.agent_label} and ${plural(x.merged, 'other member')} are told` : `Adopted; ${r.agent_label} is told`); ADM.rep = null; await refresh(); openD('directive', x.directive.id);
    } });
  };
  // Drawn from the last answer at once (no jump on the background redraw), then brought up to date.
  draw();
  api('/directive-reports?status=all').then((x) => { if (!box.isConnected || JSON.stringify(x.reports) === JSON.stringify(ADM.rep)) return; ADM.rep = x.reports; draw(); }).catch(() => {});
}

/* Projects (Work → Teams → Projects): every project, a standalone one, its name, kind and status; the Blueprint limits. */
const ADM_PST = { active: ['Active', 'ok'], paused: ['Paused', 'warn'], closed: ['Closed', 'idle'] };
const ADM_KIND = [['implementation', 'Implementation'], ['research', 'Research']];
const ADM_LIM = [['items_per_project', 'Items in a project'], ['items_per_team', 'Items in a team\'s part'], ['acs_per_fr', 'Criteria per requirement'], ['lines', 'Research lines'], ['papers', 'Papers'],
  ['claims_per_paper', 'Claims per paper'], ['title', 'Title length'], ['body', 'Text length'], ['architecture_body', 'Architecture text length'], ['fields', 'Fields length'], ['links_per_item', 'Links per item'],
  ['ops_per_write', 'Changes in one write'], ['revisions_per_item', 'Revisions kept per item'], ['reports_per_project', 'Status reports kept per project']];
/** Projects that may hold p as an ecosystem (docs/blueprint.md §3): one level deep, never p itself, no teams and only a Foundation. */
const admEcoOk = (q, p) => q.id !== p.id && !q.parent_id && !q.teams.length && Object.keys(q.counts?.by_kind || {}).every((k) => k === 'summary' || k === 'stakeholder');
/** Outside systems (docs/blueprint.md §3): one row per system, its name and an optional URL template that makes its chips links. */
const admSysRow = (s = {}) => `<div class="adm-sys" role="group" aria-label="Outside system"><input class="inp mono" data-sys="name" maxlength="24" autocomplete="off" spellcheck="false" placeholder="tracker" aria-label="System" value="${esc(s.system || '')}"><input class="inp mono" data-sys="tpl" maxlength="500" autocomplete="off" spellcheck="false" placeholder="https://tracker.example/story/{id}" aria-label="URL template (optional)" value="${esc(s.url_template || '')}"><button type="button" class="btn ghost sm ic" data-sys-del aria-label="Remove this system">${ic('x')}</button></div>`;
const admSysField = (L) => `<div class="fld"><span class="vlabel">Outside references</span><div id="admSys" class="adm-syss">${(L || []).map(admSysRow).join('')}</div><div class="row"><button type="button" class="btn ghost sm" id="admSysAdd">${ic('plus')}Add a system</button></div><p class="hint">The systems Blueprint items may point to, such as a tracker or pull requests. With a URL template that holds {id}, a reference opens that record; without one it is plain text. With no system listed, any system is accepted.</p></div>`;
/** The rows as the API takes them; an empty row is left out. */
const admSysVal = (sh) => $$('.adm-sys', sh).map((r) => ({ system: $('[data-sys="name"]', r).value.trim().toLowerCase(), url_template: $('[data-sys="tpl"]', r).value.trim() || null })).filter((s) => s.system || s.url_template);
function admPrjSheet(p, L = []) {
  let closing = false, kindOk = false;
  const ecos = L.filter((q) => q.id === p.parent_id || admEcoOk(q, p)).sort((a, b) => a.name.localeCompare(b.name));
  // An ecosystem has no kind and no teams of its own, and it cannot sit in another one.
  const eco = p.ecosystem
    ? '<p class="hint">This project is an ecosystem: it groups other projects, so it cannot sit in one.</p>'
    : selField('admPe', 'Ecosystem', [['', 'None'], ...ecos.map((q) => [q.id, q.name])], p.parent_id || '') + '<p class="hint">The ecosystem groups independent projects under a shared vision. It gives no access: grants stay per project.</p>';
  const sh = fbSheet({ title: 'Edit project', label: 'Save', fields: `<label class="fld"><span class="vlabel">Name</span><input class="inp" id="admPn" maxlength="200" value="${esc(p.name)}" autocomplete="off"></label>`
    + (p.ecosystem ? '' : selField('admPk', 'Kind', ADM_KIND, p.kind)) + '<div id="admPkfx"></div>' + selField('admPs', 'Status', [['active', 'Active'], ['paused', 'Paused'], ['closed', 'Closed']], p.status)
    + (p.ecosystem ? '' : twRow('Single team', 'Off: several teams may work on this project. On: it keeps its one team, and a second team or onboarding request is refused. Adding agents to that team still works.', switchBtn('Single team', !!p.single_team, 'id="admP1"')))
    + eco
    + (p.ecosystem ? '' : admSysField(p.external_systems))
    + (p.ecosystem ? '' : bpMeanFields(p.status_meanings))
    + `<p class="hint">Pausing or closing tells the members of its teams.</p>` + kwChecks('admPw', p.keywords) + '<p class="hint">Its teams match these keywords too.</p>'
    + `<div class="row"><button type="button" class="btn ghost sm" data-bpv="${esc(bpArg(p.id))}">${ic('graph')}Open its Blueprint</button></div>`,
  onGo: async (sh) => {
    const name = fbVal(sh, 'admPn'), b = {}, kw = kwPicked(sh, 'admPw');
    if (!name) return 'Give the project a name.';
    if (name !== p.name) b.name = name;
    if ($('#admPk', sh) && $('#admPk', sh).value !== p.kind) b.kind = $('#admPk', sh).value;
    if ($('#admPs', sh).value !== p.status) b.status = $('#admPs', sh).value;
    if ($('#admPw', sh) && !kwSame(kw, p.keywords)) b.keywords = kw;
    const one = $('#admP1', sh); if (one && (one.getAttribute('aria-checked') === 'true') !== !!p.single_team) b.single_team = one.getAttribute('aria-checked') === 'true';
    const pe = $('#admPe', sh); if (pe && (pe.value || null) !== (p.parent_id || null)) b.parent_id = pe.value || null;
    if ($('#admSys', sh)) {
      const sys = admSysVal(sh);
      const bad = sys.find((s) => !/^[a-z][a-z0-9-]{0,23}$/.test(s.system));
      if (bad) return `"${bad.system || bad.url_template}": a system is a short lower-case word, a letter then letters, digits or hyphens (tracker, pr).`;
      const badT = sys.find((s) => s.url_template && (!s.url_template.startsWith('https://') || !s.url_template.includes('{id}')));
      if (badT) return `The URL template of ${badT.system} must start with https:// and a fixed host, and contain {id} only in the path or the query.`;
      if (JSON.stringify(sys) !== JSON.stringify(p.external_systems || [])) b.external_systems = sys;
    }
    const mean = bpMeanDiff(sh, p.status_meanings); if (mean) b.status_meanings = mean;
    if (!Object.keys(b).length) return null;
    // A new kind on a populated project: first say what changes and what stays, then save on the second press.
    if (b.kind && p.counts?.items && !kindOk) {
      const fx = await api(`${bpP(p.id)}/kind-effects?kind=${encodeURIComponent(b.kind)}`);
      $('#admPkfx', sh).innerHTML = `<div class="vnote"><div><b>What changes</b><ul>${fx.changes.map((t) => `<li>${esc(t)}</li>`).join('')}</ul><b>What stays</b><ul>${fx.keeps_text.map((t) => `<li>${esc(t)}</li>`).join('')}</ul></div></div>`;
      kindOk = true; $('#fbGo', sh).textContent = 'Change kind'; return 'Read what changes, then press Change kind to save.';
    }
    if (b.status === 'closed' && !closing) { closing = true; $('#fbGo', sh).textContent = 'Close project'; $('#fbGo', sh).className = 'btn bad lg'; return 'Its teams are told to stop. Press Close project to go on.'; }
    await api(bpP(p.id), 'PATCH', b); toast(b.status === 'closed' ? 'Project closed' : 'Project saved'); await refresh(); reopen(); return null;
  } });
  // A changed status takes back the armed Close project button; a changed kind takes back Change kind.
  $('#admPs', sh).onchange = () => { if (!closing) return; closing = false; $('#fbGo', sh).textContent = 'Save'; $('#fbGo', sh).className = 'btn pri lg'; $('#fbErr', sh).textContent = ''; };
  if ($('#admPk', sh)) $('#admPk', sh).onchange = () => { if (!kindOk) return; kindOk = false; $('#admPkfx', sh).innerHTML = ''; $('#fbGo', sh).textContent = 'Save'; $('#fbErr', sh).textContent = ''; };
  if ($('#admP1', sh)) $('#admP1', sh).onclick = (e) => flipSwitch(e.currentTarget);
  const sysBox = $('#admSys', sh);
  if (sysBox) {
    $('#admSysAdd', sh).onclick = () => { if ($$('.adm-sys', sysBox).length >= 20) { $('#fbErr', sh).textContent = 'A project lists at most 20 outside systems.'; return; } sysBox.insertAdjacentHTML('beforeend', admSysRow()); $('.adm-sys:last-child [data-sys="name"]', sysBox).focus(); };
    sysBox.addEventListener('click', (e) => {
      const d = e.target.closest('[data-sys-del]'); if (!d) return;
      const r = d.closest('.adm-sys'), next = r.nextElementSibling || r.previousElementSibling;
      r.replaceWith();
      ((next && $('[data-sys="name"]', next)) || $('#admSysAdd', sh)).focus();
    });
  }
}
function admPrjNew() {
  const sh = fbSheet({ title: 'New project', label: 'Create project', fields: `<label class="fld"><span class="vlabel">Name</span><input class="inp" id="admNn" maxlength="200" autocomplete="off"></label>`
    + `<label class="fld"><span class="vlabel">Key</span><input class="inp mono" id="admNk" maxlength="8" autocomplete="off" spellcheck="false" placeholder="CNV"></label><p class="hint">2 to 8 capital letters. It cannot be changed later.</p>`
    + selField('admNkd', 'Kind', ADM_KIND, 'implementation') + kwChecks('admNw', S.kws?.default || []) + '<p class="hint">No team yet: assign teams from their settings.</p>',
  onGo: async (s) => {
    const name = fbVal(s, 'admNn'), key = fbVal(s, 'admNk').toUpperCase();
    if (!name) return 'Give the project a name.';
    if (!/^[A-Z]{2,8}$/.test(key)) return 'The key is 2 to 8 capital letters, such as CNV.';
    const r = await post('/projects', { key, name, kind: $('#admNkd', s).value, ...($('#admNw', s) ? { keywords: kwPicked(s, 'admNw') } : {}) }); toast(`Project ${r.project.key} created`); reopen(); return null;
  } });
  // The key follows the name's initials until the operator types one.
  let typed = false; const k = $('#admNk', sh);
  k.oninput = () => { typed = true; k.value = k.value.toUpperCase().replace(/[^A-Z]/g, ''); };
  $('#admNn', sh).oninput = (e) => { if (typed) return; const w = e.target.value.toUpperCase().replace(/[^A-Z ]+/g, ' ').split(/\s+/).filter(Boolean); k.value = (w.length > 1 ? w.map((x) => x[0]).join('') : (w[0] || '').slice(0, 3)).slice(0, 8); };
}
function admLimSheet(lim) {
  const rows = ADM_LIM.filter(([k]) => k in lim.limits).map(([k, l]) => row({ as: 'div', title: l, meta: `Default ${admNum(lim.defaults[k])} · max ${admNum(lim.max[k])}${k === 'reports_per_project' ? ' · older ones archived to the export' : ''}`,
    trail: `<input class="inp sm w-num" type="number" min="1" max="${lim.max[k]}" step="1" data-admlim="${k}" value="${lim.limits[k]}" aria-label="${esc(l)}"><button type="button" class="btn ghost sm" data-admlim-def="${k}" aria-label="Reset ${esc(l)} to its default">Reset</button>` }));
  const sh = fbSheet({ title: 'Blueprint limits', label: 'Save limits', fields: `<p class="hint">For every project. Agents' writes over a limit are refused.</p><div class="adm-lims">${rows.join('')}</div><div class="row"><button type="button" class="btn ghost sm" id="admLimAll">Reset all to defaults</button></div>`,
    onGo: async (s) => {
      const b = {};
      for (const i of $$('[data-admlim]', s)) {
        const k = i.dataset.admlim, v = Number(i.value), max = lim.max[k];
        if (!Number.isInteger(v) || v < 1 || v > max) return `${i.getAttribute('aria-label')}: a whole number from 1 to ${admNum(max)}.`;
        if (v === lim.defaults[k]) { if (lim.limits[k] !== v) b[k] = null; } else if (v !== lim.limits[k]) b[k] = v;
      }
      if (!Object.keys(b).length) return null;
      await api('/settings/blueprint', 'PUT', { limits: b }); toast(`${plural(Object.keys(b).length, 'limit')} saved`); reopen(); return null;
    } });
  sh.addEventListener('click', (e) => { const d = e.target.closest('[data-admlim-def]'); if (d) $(`[data-admlim="${d.dataset.admlimDef}"]`, sh).value = lim.defaults[d.dataset.admlimDef]; });
  arm($('#admLimAll', sh), () => run(async () => { await api('/settings/blueprint', 'PUT', { limits: Object.fromEntries(Object.keys(lim.limits).map((k) => [k, null])) }); closeSheet(); toast('Limits back to their defaults'); reopen(); }), 'Reset all: confirm');
}
/* Keywords (docs/proposals/team-keywords.md): the known list is a hub setting (Projects → Keywords, also in the Teams page menu),
   and the checkboxes set a project's or a team's keywords. A team matches a keyword when it or its project has it. */
const kwChecks = (id, sel = [], from = []) => {
  const L = tmKws();
  if (!L.length) return '<p class="hint">No keywords yet. Add them in Projects → Keywords.</p>';
  return `<fieldset class="rp-kinds kw-pick" id="${id}"><legend class="vlabel">Keywords</legend>${L.map((k) => `<label class="chk-row"><input type="checkbox" data-kw="${esc(k)}"${sel.includes(k) ? ' checked' : ''}><span>${esc(k)}${from.includes(k) ? '<span class="faint"> · also from the project</span>' : ''}</span></label>`).join('')}</fieldset>`;
};
const kwPicked = (sh, id) => $$(`#${id} [data-kw]`, sh).filter((x) => x.checked).map((x) => x.dataset.kw);
const kwSame = (a = [], b = []) => a.length === b.length && a.every((x) => b.includes(x));
const kwText = (L) => (L && L.length ? esc(L.join(', ')) : '<span class="faint">None</span>');
const kwUse = (u) => (u && (u.projects || u.teams) ? [u.projects ? plural(u.projects, 'project') : '', u.teams ? plural(u.teams, 'team') : ''].filter(Boolean).join(' · ') : 'Not used');
async function kwLoad() { S.kws = await api('/settings/keywords'); return S.kws; }
/* The known list: add, reorder, remove. Removing a keyword in use says what it comes off before the save. */
async function kwSheet(anchor) {
  const cur = await kwLoad(), L = cur.keywords.slice(), fold = (k) => k.toLowerCase();
  // A centred sheet, not a 260 px popover from the button: the rows need room for a 40-character keyword and three buttons.
  void anchor;
  const sh = fbSheet({ title: 'Keywords', label: 'Save keywords',
    fields: '<p class="hint">A team matches when it or its project has the keyword.</p><div id="kwL" class="kw-list"></div>'
      + `<div class="row kw-add"><input class="inp" id="kwN" maxlength="40" placeholder="New keyword" aria-label="New keyword" autocomplete="off"><button type="button" class="btn sm" id="kwAdd">${ic('plus')}Add</button></div><p class="hint kw-gone" id="kwGone" hidden></p>`,
    onGo: async () => {
      if (L.length === cur.keywords.length && L.every((k, i) => k === cur.keywords[i])) return null;
      S.kws = await api('/settings/keywords', 'PUT', { keywords: L });
      toast('Keywords saved'); await refresh(); reopen(); return null;
    } });
  const box = $('#kwL', sh), inp = $('#kwN', sh), err = $('#fbErr', sh);
  const draw = (focus) => {
    box.innerHTML = L.length ? L.map((k, i) => row({ as: 'div', title: k, meta: cur.usage[k] ? kwUse(cur.usage[k]) : 'New',
      trail: `<button type="button" class="btn sm ic" data-kwmv="${i}" data-d="-1" aria-label="Move ${esc(k)} up"${i ? '' : ' disabled'}>${ic('up')}</button>`
        + `<button type="button" class="btn sm ic" data-kwmv="${i}" data-d="1" aria-label="Move ${esc(k)} down"${i === L.length - 1 ? ' disabled' : ''}>${ic('down')}</button>`
        + `<button type="button" class="btn sm ic" data-kwrm="${i}" aria-label="Remove ${esc(k)}">${ic('x')}</button>` })).join('') : none('sl', 'No keywords: Teams shows All only');
    const gone = cur.keywords.filter((k) => !L.some((x) => fold(x) === fold(k)) && (cur.usage[k]?.projects || cur.usage[k]?.teams));
    const P = gone.reduce((a, k) => a + cur.usage[k].projects, 0), T = gone.reduce((a, k) => a + cur.usage[k].teams, 0), g = $('#kwGone', sh);
    g.hidden = !gone.length;
    g.textContent = gone.length ? `Saving takes ${gone.join(', ')} off ${[P ? plural(P, 'project') : '', T ? plural(T, 'team') : ''].filter(Boolean).join(' and ')}.` : '';
    // Focus stays on the control that moved (or its pair when it reached an end), else on the field.
    if (focus) { let el = $(focus, box); if (!el || el.disabled) el = $(focus.replace(/\[data-d="-?1"\]/, ':not([disabled])'), box); (el || inp).focus(); }
  };
  const add = () => {
    const k = inp.value.replace(/\s+/g, ' ').trim(); err.textContent = '';
    if (!k) return;
    if (fold(k) === 'all') { err.textContent = '"All" is the filter\'s own choice.'; return; }
    if (L.some((x) => fold(x) === fold(k))) { err.textContent = `${k} is already on the list.`; return; }
    if (L.length >= 20) { err.textContent = 'At most 20 keywords.'; return; }
    L.push(k); inp.value = ''; draw(); inp.focus();
  };
  $('#kwAdd', sh).onclick = add;
  inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); add(); } });
  box.addEventListener('click', (e) => {
    const mv = e.target.closest('[data-kwmv]'), rm = e.target.closest('[data-kwrm]');
    if (mv) { const i = +mv.dataset.kwmv, d = +mv.dataset.d, j = i + d; if (j < 0 || j >= L.length) return; [L[i], L[j]] = [L[j], L[i]]; draw(`[data-kwmv="${j}"][data-d="${d}"]`); }
    else if (rm) { const i = +rm.dataset.kwrm; L.splice(i, 1); draw(L.length ? `[data-kwrm="${Math.min(i, L.length - 1)}"]` : '#kwN'); }
  });
  draw();
}

/* Agent owners (docs/authorization.md#agent-owners): the console users who may own an agent, for an owner select. The
   signed-in admin is preselected where a new agent is made, so the owner is always one the admin saw and chose. */
const ownUsers = async () => ((await api('/users').catch(() => ({ users: [] }))).users || []).filter((u) => u.status === 'active');
const ownLabel = (u) => u.display_name || u.username;
const ownOpts = (L, sel) => `<option value=""${sel ? '' : ' selected'}>No owner</option>${L.map((u) => `<option value="${esc(u.id)}"${u.id === sel ? ' selected' : ''}>${esc(ownLabel(u))}${u.id === S.me?.id ? ' (you)' : u.role === 'member' ? ' · member' : ''}</option>`).join('')}`;
const ownField = (id, L, sel) => `<label class="fld"><span class="vlabel">Owner</span><select class="sel" id="${id}" aria-label="Owner">${ownOpts(L, sel)}</select></label>`;
/* Change owner: the admin names the console user who owns the agent, or none (PATCH /api/agents/:id {owner_id}). */
async function admOwnerSheet(a, owner, done) {
  const L = await ownUsers();
  fbSheet({ title: 'Change owner', label: 'Save', fields: ownField('admOw', L, owner?.id || '') + '<p class="hint">The person this agent belongs to. Owning an agent gives no admin power, and the agent no permission by itself.</p>',
    onGo: async (sh) => {
      const v = fbVal(sh, 'admOw') || null;
      if (v === (owner?.id || null)) return null;
      await api('/agents/' + encodeURIComponent(a.id), 'PATCH', { owner_id: v });
      toast(v ? `${a.label} now belongs to ${ownLabel(L.find((u) => u.id === v))}` : `${a.label} has no owner now`); await refresh(); done(); return null;
    } });
}
/* A PC's name (PATCH /api/pcs/:id): the Add PC rules, an inline error for a taken name. The PC is known by its id, so only the label changes. */
function pcRenameSheet(p, anchor, done) {
  fbSheet({ title: 'Rename PC', anchor, label: 'Rename',
    fields: `<label class="fld"><span class="vlabel">Name</span><input class="inp mono" id="pcRnI" maxlength="63" value="${esc(p.name)}" autocomplete="off" autocapitalize="none" spellcheck="false"></label>`
      + '<p class="hint">Lowercase letters, digits and dashes. Its keys, agents and bridge are not affected. Files on the PC itself keep the old name until the PC is set up again.</p>',
    onGo: async (sh) => {
      const n = fbVal(sh, 'pcRnI');
      if (!n) return ['Type a name.', 'pcRnI'];
      if (n === p.name) return ['Type a new name, or cancel.', 'pcRnI'];
      if (!/^[a-z0-9][a-z0-9-]{0,62}$/.test(n)) return ['Use lowercase letters, digits and dashes, up to 63.', 'pcRnI'];
      try { await api('/pcs/' + encodeURIComponent(p.id), 'PATCH', { name: n }); } catch (e) { if (e.status === 409 || e.status === 400) return [e.message, 'pcRnI']; throw e; }
      toast(`Renamed to ${n}`); await done(); return null;
    } });
}
/* An app key's limit of live logins (PUT /api/keys/:id/live-limit): a whole number from 1 to 500, checked here and again by the hub.
   A login over the limit is refused; logins already live go on, and the new limit applies at the next login. */
function liveLimitSheet(k, kp, anchor, done) {
  fbSheet({ title: 'Login limit', anchor, label: 'Save',
    fields: `<label class="fld"><span class="vlabel">Live logins at most</span><input class="inp mono" id="kLimI" type="number" inputmode="numeric" min="1" max="500" step="1" value="${esc(String(k.max_live_sessions))}" autocomplete="off"></label>`
      + '<p class="hint">From 1 to 500. A new app key starts at 100. The limit applies at the next login; logins already live go on.</p>',
    onGo: async (sh) => {
      const raw = fbVal(sh, 'kLimI'), n = Number(raw);
      if (!raw) return ['Type a number from 1 to 500.', 'kLimI'];
      if (!Number.isInteger(n) || n < 1 || n > 500) return ['Use a whole number from 1 to 500.', 'kLimI'];
      if (n === k.max_live_sessions) return ['Type a new limit, or cancel.', 'kLimI'];
      try { await api(kp + '/live-limit', 'PUT', { max_live_sessions: n }); } catch (e) { if (e.status === 400) return [e.message, 'kLimI']; throw e; }
      await done(); return null;
    } });
}
/* Agents: the name (PATCH /api/agents/:id). An agent is in the projects of its teams (docs/directives.md#project-reach):
   the old free-text project label is no longer set here. */
async function admAgentSheet(a, done) {
  fbSheet({ title: 'Rename', label: 'Save', fields: `<label class="fld"><span class="vlabel">Name</span><input class="inp" id="admAn" maxlength="80" value="${esc(a.label)}" autocomplete="off"></label>`
    + '<p class="hint">An agent is in the projects of its teams: add it to a team, or move its team, to change them.</p>',
  onGo: async (sh) => {
    const label = fbVal(sh, 'admAn');
    if (!label) return 'Give the agent a name.';
    if (label === a.label) return null;
    await api('/agents/' + encodeURIComponent(a.id), 'PATCH', { label });
    toast(`Renamed to ${label}`); await refresh(); done(); return null;
  } });
}

/* A team's past recruit requests and the start-overs of its project (#thist/<team>|<status>). */
const ADM_RQ_ST = { pending: ['Waiting', 'warn'], approved: ['Approved', 'ok'], denied: ['Denied', 'idle'] };
const ADM_RP_ST = { open: ['Open', 'info'], applied: ['Applied', 'ok'], cancelled: ['Cancelled', 'idle'] };
const admTeamHistRow = (t, id) => {
  const R = t.recruits || [], w = R.filter((q) => q.status === 'pending').length;
  return row({ lead: ic('rot'), title: 'Recruits and start-overs', meta: raw([R.length ? esc(plural(R.length, 'recruit request')) : 'No recruit requests', w ? `<span class="warn-t">${w} waiting</span>` : ''].filter(Boolean).join(' · ')), chev: true, attrs: { 'data-go': 'thist', 'data-arg': id, title: 'Open past recruit requests and start-overs' } });
};
/* What a start-over changed against the snapshot it saved: added, changed, removed and links (as on the Proposals screen). */
function admDiff(d) {
  const L200 = (L, f) => L.slice(0, 200).map(f).join('') + (L.length > 200 ? `<li class="faint">and ${L.length - 200} more</li>` : '');
  const chg = (c) => {
    const ch = [];
    if (c.what.includes('title')) ch.push(`title <del>${esc(c.was.title)}</del> <ins>${esc(c.title)}</ins>`);
    if (c.what.includes('status')) ch.push(`status <del>${esc(bpLabel(c.was.status))}</del> <ins>${esc(bpLabel(c.status))}</ins>`);
    const rest = c.what.filter((w) => w !== 'title' && w !== 'status').map((w) => RP_WHAT[w] || w);
    if (rest.length) ch.push(`${esc(rest.join(', '))} changed`);
    if (!c.what.includes('title')) ch.unshift(esc(c.title));
    return `<li>${bpK(c.key)} ${ch.join(' · ')}</li>`;
  };
  const grp = (label, L, f) => (L.length ? `${overline(label, L.length)}<ul class="bp-diff">${L200(L, f)}</ul>` : '');
  const links = [...d.links.added.map((l) => ['+', l]), ...d.links.removed.map((l) => ['-', l])];
  const any = d.added.length + d.changed.length + d.removed.length + links.length;
  return (any ? grp('Added', d.added, (x) => `<li>${bpK(x.key)} <ins>${esc(x.title)}</ins></li>`) + grp('Changed', d.changed, chg) + grp('Removed', d.removed, (x) => `<li>${bpK(x.key)} <del>${esc(x.title)}</del></li>`)
    + grp('Links', links, ([s, l]) => (s === '+' ? `<li><ins>${esc(l)}</ins></li>` : `<li><del>${esc(l)}</del></li>`)) : none('check', 'Nothing differs from the snapshot'))
    + `<p class="hint">${plural(d.unchanged, 'item')} unchanged.</p>`;
}

/* Permission templates: the list, a template's rules, and a form for a new one (there is no edit or delete route). */
