const admRuleRow = (r = { effect: 'allow', actions: [], resource: '' }) => `<div class="adm-rule"><select class="sel" data-f="effect" aria-label="Effect"><option value="allow"${r.effect === 'allow' ? ' selected' : ''}>Allow</option><option value="deny"${r.effect === 'deny' ? ' selected' : ''}>Deny</option></select>`
