      dbar: { title: 'Projects', menu: [{ label: 'Blueprint limits', icon: 'sl', fn: () => admLimSheet(lim) }, { label: 'Keywords', icon: 'sl', fn: () => run(() => kwSheet(null)) }] },
      b: `<div class="kd-grid"><div class="kd-col">${list}</div><div class="kd-col">${kws}${limits}</div></div><div class="actionbar only-m"><button type="button" class="btn pri lg" id="admPrjNewM">${ic('plus')}New project</button></div>`,
