function sectionBar(t) { const a = areaOf(t); return a && !(a === 'agents' && TEAM_SCREENS.has(t)) ? $(SECTION_BARS[a]) : null; }
/* The shown section bar is the first row of the view card; on Home, with no card, the Work bar sits above the overview. */
