          $('#kX', sh).onclick = (ev) => { const b = ev.target.closest('button'); if (b) { closeSheet(); act(() => api(kp, 'PATCH', { expires_at: +b.dataset.d ? Date.now() + +b.dataset.d * 864e5 : null }), 'Saved'); } };
