          const sh = openSheet({ title: 'PC binding', anchor, html: `<p>A bound key logs in only from its PC. Applies at the next login.</p>${opt('', 'Free (any permitted PC)')}${pcs.map((p) => opt(p.id, `Use only from ${p.name}`)).join('')}` });
