const tzBar = () => `<div class="tg-zoom" id="tgZoom" role="group" aria-label="Zoom"><button type="button" class="tog" data-tz="ov" aria-pressed="true" title="Overview: agents as dots (Esc)">Overview</button><input type="range" class="only-d" min="${TZ_MIN}" max="${TZ_MAX}" step="0.1" value="${TZ.z}" aria-label="Zoom"><button type="button" class="tog" data-tz="det" aria-pressed="false" title="Details: role names and links">Details</button></div>`;
