  return narrow ? `<div class="ag-cols is-one">${[...cards].sort((x, y) => x.narrow - y.narrow).map(one).join('')}</div>`
    : `<div class="ag-cols">${[1, 2].map((n) => `<div class="ag-col">${cards.filter((c) => c.col === n).map(one).join('')}</div>`).join('')}</div>`;
