  if (narrow) { by('narrow').forEach((c) => box.append(c)); $$('.ag-col', box).forEach((c) => c.remove()); }
  else { const cols = [1, 2].map(() => Object.assign(document.createElement('div'), { className: 'ag-col' })); by('i').forEach((c) => cols[c.dataset.col - 1].append(c)); box.append(...cols); }
