        $('#obPx').onclick = (e) => { E.project = { ...E.project, existing: flipSwitch(e.currentTarget) }; };
        $('#obPm').onclick = (e) => { E.project = { ...E.project, more_teams: flipSwitch(e.currentTarget) }; };
