        const roles = E.roles.map((r) => ({ ...r, count: Math.floor(+r.count) || 1, folders: (r.folders || []).filter((f) => f.path) }));
        const team = { ...E.team }; delete team.id;
        const rules = keptRules();
        if (rules.some((x) => !x.title || !x.text)) { return toast('A kept rule needs a title and its text', true); }
        const standard = newTeam ? stdEdits() : [], requirements = newTeam ? keptReqs() : [];
