const TM_POOL = 'Unassigned agents';
/* Topology is a view, not a grouping: its focus is project:<name>, team:<id> or agent:<id>; k= and q= do not apply. */
const TM_FOCUS = /^(project:[^]{1,200}|team:[a-z]+[_-][A-Za-z0-9_-]+|agent:[a-z]+[_-][A-Za-z0-9_-]+)$/;
