  const x = { o: p.get('o') === 'act' ? '' : p.get('o') || '', q: (p.get('q') || '').slice(0, 100), k: (p.get('k') || '').slice(0, 40) };
  return TM_ORG.some(([k]) => k === x.o) ? x : null;
