  const st = t.status !== 'running' && !o.noSt ? `<span class="${t.status === 'paused' ? 'warn-t' : t.status === 'stopped' ? 'bad-t' : ''}">${esc(t.status === 'paused' ? [pauseUntil(t), t.paused_note].filter(Boolean).join(' · ') : cap(t.status))}</span>` : '';
  const proj = o.noProj || x.proj === NO_PROJECT ? '' : esc(x.proj);
