document.addEventListener('click', (e) => { const b = e.target.closest?.('[data-reassign]'); if (!b) return; e.preventDefault(); e.stopPropagation(); const [tm, id] = b.dataset.reassign.split('|'); run(() => reassignSheet(tm, id, b)); }, true);
