  open: ['Open', 'idle'], passing: ['Passing', 'ok'], failing: ['Failing', 'bad'], waived: ['Waived', 'idle'],
  active: ['Active', 'ok'], parked: ['Parked', 'idle'], closed: ['Closed', 'idle'],
  untested: ['Untested', 'idle'], testing: ['Testing', 'info'], confirmed: ['Confirmed', 'ok'], refuted: ['Refuted', 'bad'], inconclusive: ['Inconclusive', 'warn'], answered: ['Answered', 'ok'],
  proposed: ['Proposed', 'warn'], accepted: ['Accepted', 'ok'], superseded: ['Superseded', 'idle'], rejected: ['Rejected', 'idle'],
  planned: ['Planned', 'idle'], in_progress: ['In progress', 'info'], reached: ['Reached', 'ok'], missed: ['Missed', 'bad'], released: ['Released', 'ok'], cancelled: ['Cancelled', 'idle'],
  drafting: ['Drafting', 'info'], submitted: ['Submitted', 'acc'], published: ['Published', 'ok'], final: ['Final', 'idle'], cut: ['Cut', 'idle'],
  mitigated: ['Mitigated', 'ok'], resolved: ['Resolved', 'ok'],
  supported: ['Supported', 'ok'], weak: ['Weak', 'warn'], unsupported: ['Unsupported', 'bad'], contradicted: ['Contradicted', 'bad'],
  on_track: ['On track', 'ok'], at_risk: ['At risk', 'warn'], off_track: ['Off track', 'bad'], unknown: ['No health', 'idle'],
