const BP_TABS = [null, ['1', 'Project Foundation'], ['2', 'Product Requirements'], ['3', 'Decisions & Architecture'], ['4', 'Planning & Execution'], ['5', 'Tracking & Governance'], ['6', 'Appendix']];
