const BP_KIND = { fr: 'Requirement', nfr: 'Non-functional requirement', ac: 'Acceptance criterion', module: 'Module', line: 'Research line', hypothesis: 'Hypothesis', question: 'Question', finding: 'Finding',
  decision: 'Decision', architecture: 'Architecture', milestone: 'Milestone', release: 'Release', paper: 'Paper', claim: 'Paper claim', report: 'Status report', risk: 'Risk', issue: 'Issue',
  summary: 'Executive summary', stakeholder: 'Stakeholder', term: 'Term', reference: 'Reference' };
const BP_REL = { delivers: 'delivers', ships: 'ships', governs: 'governs', supersedes: 'supersedes', threatens: 'threatens', blocks: 'blocks', evidence: 'evidence', studies: 'studies' };
