  return row({ ...bpTM(it.key, it.title, raw(mt), { 'data-bp': bpItemArg(pid, it.key), ...(it.plain?.issues?.length ? { title: it.plain.issues.map(cap).join('; ') } : {}) }), meta: m, trail: extra.trail ?? bpSt(it.support || it.status), chev: true, cls: it.status === 'dropped' || it.status === 'cut' ? 'dropped' : '' });
