    const kpis = kind === 'research' || lines.length ? (() => { const h = by('hypothesis'); return `<div class="bp-kpis">${[['Hypotheses', h.length], ['Confirmed', h.filter((x) => x.status === 'confirmed').length], ['Refuted', h.filter((x) => x.status === 'refuted').length], ['Findings', by('finding').length]].map(([l, v]) => `<div class="bp-kpi"><b>${v}</b><span class="meta">${l}</span></div>`).join('')}</div>`; })() : '';
    return kind === 'research' ? kpis + lineHtml + modHtml + nfrHtml + topQHtml : modHtml + nfrHtml + topQHtml + kpis + lineHtml;
