    const ov = a ? `<div class="bp-c bp-arch-ov">${overline('Architecture overview', undefined, `<button type="button" class="btn ghost sm ml-auto" data-bp="${esc(bpItemArg(pid, a.key))}">Open</button>`)}${bpArchText(a.body || a.title)}</div>` : '';
    const log = d.length ? `<div class="bp-c bp-arch-log">${overline('Decision log')}${d.map((x) => row({ lead: `<span class="bp-date">${planDate(bpF(x, 'decided_at') || x.created_at)}</span>`, ...bpTM(x.key, x.title, bpDecSource(x.fields || {}), { 'data-bp': bpItemArg(pid, x.key) }), trail: bpSt(x.status), chev: true })).join('')}</div>` : '';
