      + (rel.length ? card('Release plan', rel.map((r) => bpRow(pid, r, [bpF(r, 'target_at') ? planDate(bpF(r, 'target_at')) : '', bpLinks(r, 'ships').join(', ')].filter(Boolean).join(' · ') || 'No scope yet')).join('')) : '')
