  const state = pr ? ['Waits for your review', 'warn'] : r.source === 'import' ? ['Docs import', 'idle'] : ['Coordinator rebuilding', 'idle'];
  return `<div class="bp-c bp-rp" role="region" aria-label="Start over: ${esc(rpScope(r))}"><div class="bp-prop-h"><span class="bp-prop-t"><b>Starting over · ${esc(rpScope(r))}</b>`
