    + `<div class="bp-acts"><a class="btn sm" href="/api/replans/${esc(encodeURIComponent(r.id))}/snapshot.md" download>${ic('dl')}Snapshot</a><button type="button" class="btn sm" data-rp-cancel="${esc(r.id)}">${ic('x')}Cancel start over</button>`
    + (pr ? (tab === 'prop' ? '' : `<button type="button" class="btn pri sm" data-bpv="${esc(go('prop'))}">Review</button>`) : `<button type="button" class="btn sm" data-rp-submit="${esc(r.id)}">File the review</button>`) + '</div></div>';
