    const dec = (e) => (e.kind === 'hypothesis' ? e.status === 'confirmed' : e.kind === 'finding' ? ['medium', 'high'].includes(e.confidence) : e.kind === 'fr' || e.kind === 'nfr' ? e.status === 'verified' : e.kind === 'ac' ? e.status === 'passing' : false);
    const against = (e) => (e.kind === 'hypothesis' ? e.status === 'refuted' : e.kind === 'fr' || e.kind === 'nfr' ? e.status === 'dropped' : e.kind === 'ac' ? e.status === 'failing' : false);
    const nDec = flat.filter(dec).length, cutC = it.status === 'cut';
