    const nested = new Set((d.chain || []).flatMap((e) => (e.from || []).map((x) => x.key)));
    const evRow = (e, sub) => row({ ...bpTM(e.key, e.title, `${BP_KIND[e.kind] || e.kind}${e.confidence ? ` · ${cap(e.confidence)} confidence` : ''}`, { 'data-bp': bpItemArg(pid, e.key) }), trail: bpSt(e.status), chev: true, cls: `bp-cr${sub ? ' bp-nest' : ''}` });
    const evRows = (d.chain || []).filter((e) => !nested.has(e.key)).map((e) => evRow(e, false) + (e.from || []).map((x) => evRow(x, true)).join('')).join('');
    // The claim's own text (§5.1) sits under its head and above the verdict; a claim's title is its statement, so an empty summary says nothing.
    main = `<div class="bp-ph">${bpPh(it, d.plain)}<p class="meta"><button type="button" class="bp-inl" data-bp="${esc(bpItemArg(pid, it.parent))}">${esc(it.parent)}</button> · ${f.part ? esc(cap(f.part)) : 'Unplaced'}${cutC ? '' : ` · ${esc(bpLabel(it.status))} wording`}</p>${xr}${bpStand(d)}${bpBody(it, d.plain, '', srcs)}</div>`
      + `<section class="sec bp-sec"><div class="bp-rd">${bpSt(cutC ? 'cut' : d.support)}<span class="of">${esc(why)}</span></div>${flat.length ? overline('Evidence', flat.length) + evRows : ''}</section>`;
    side = '';
    if (has('add_evidence')) { acts += `<button type="button" class="btn sm" id="bpEvB">${ic('link')}Add evidence</button>`; after.push(() => { $('#bpEvB').onclick = (e) => bpAddEvidence(pid, it.key, e.currentTarget); }); }
    if (has('cut_claim')) menu.push({ label: 'Cut claim', icon: 'x', bad: true, fn: () => bpCut(pid, it.key, $('[data-dbar-more]')) });
