const blGist = (k) => { const g = k.short_summary || k.short_summary_hub || '';
  return g ? `<div class="bl-sum"><p class="bl-gist">${esc(g)}</p><button type="button" class="btn ghost sm bl-more" data-gist aria-expanded="false" hidden>Show all</button></div>` : ''; };
const blTaskRow = (k, teamName, noDesc = 'No description', tagged = true) => { const rest = [k.postponed_at && !tagged ? `Postponed ${ago(k.postponed_at)} ago` : '', teamName, (k.refs || []).join(', '), k.short_summary || k.short_summary_hub ? '' : noDesc].filter(Boolean).join(' · ');
  // Phones lead the meta line with the tags; with nothing after them, no trailing separator.
  const tags = !tagged ? '' : rest ? tkTagMeta(k) : (k.tags || []).length ? `<span class="only-m">${esc(k.tags.map((x) => '#' + x).join(' '))}</span>` : '';
  const r = row({ title: k.title, chev: tagged, trail: tagged ? tkTagTrail(k) : '', attrs: { 'data-task': `${k.team_id}|${k.id}` }, meta: raw(tags + esc(rest)) });
  return tagged ? r + blGist(k) : { row: r, gist: blGist(k) }; };
/* Show all appears only where the clamp cuts the text; it is checked after each render and on resize. */
const gistFit = (root = document) => $$('.bl-sum', root).forEach((s) => { const p = s.firstElementChild, b = s.lastElementChild;
  if (p.classList.contains('open')) return; b.hidden = p.scrollHeight <= p.clientHeight + 1; });
function gistToggle(b) { const p = b.previousElementSibling, o = !p.classList.contains('open'); p.classList.toggle('open', o); b.setAttribute('aria-expanded', String(o)); b.textContent = o ? 'Show less' : 'Show all'; }
let gistT = 0; addEventListener('resize', () => { clearTimeout(gistT); gistT = setTimeout(() => gistFit(), 150); });
/* Home's card and Work → Backlog (blNoDesc): a task without a description names its team and refs alone, and says so only when nothing else would show. */
const blNoDesc = (k, teamName) => (teamName || (k.refs || []).length ? '' : 'No description written');
const backlogRow = (k, teamName, noDesc) => { const c = blTaskRow(k, teamName, noDesc, false); return `<div class="bl-it"><div class="bl-h">${c.row}${backlogBtns(k.team_id, k)}</div>${c.gist}</div>`; };
