  const title = (x) => raw(`${x.reported_by && !x.reviewed_at ? pill('New', 'info') + ' ' : ''}${x.copy_of ? pill('Same as ' + ruleOf(x.copy_of), 'warn') + ' ' : ''}${esc(x.title)}`);
  // The row is a div with role=button, so its trail action is a button of its own (not nested in the row's).
  const drow = (x, meta, trail = dirReadPill(x), cls = '') => row({ as: 'div', title: title(x), meta, trail, chev: true, cls, attrs: { 'data-tdir': open(x) }, extra: `tabindex="0" role="button" aria-label="${esc(x.title)}"` });
  const keepOff = (x) => adm ? `<button type="button" class="btn sm tdir-act only-d" data-tdir-off="${esc(x.id)}">Not for this team</button><button type="button" class="btn ic sm tdir-act only-m" data-tdir-more="${esc(x.id)}" aria-label="More for ${esc(x.title)}" title="More" aria-haspopup="menu">${ic('more')}</button>` : '';
  // An exemption that is not this team's own (a project, an agent, another team) asks first: lifting it reaches past this team.
