    members: () => (copies.length && adm ? vtools(`<button type="button" class="btn sm" data-tdir-fold>Fold ${plural(copies.length, 'copy', 'copies')}${into.length === 1 ? ` into ${into[0]}s` : ''}</button>`) : '')
