  const tabs = `<nav class="tabs" role="tablist" aria-label="Directives by who they are for">${TDIR_TABS.map(([k, l]) => `<button type="button" role="tab" class="${k === tab ? 'on' : ''}" aria-selected="${k === tab}" data-tdirs-tab="${esc(tdirArg(teamId, k))}">${l}<span class="cnt">${n[k]}</span></button>`).join('')}</nav>`;
