      $$('#twRec button').forEach((b) => (b.onclick = () => { markEdited(); $$('#twRec button').forEach((x) => x.classList.toggle('on', x === b)); $('.tw-rec').hidden = b.dataset.rec === 'off'; }));
      $$('.tw [role=switch]').forEach((b) => (b.onclick = () => { markEdited(); flipSwitch(b); }));
