const bt = (label, attrs, cls = '') => `<button class="btn${cls ? ' ' + cls : ''}" ${attrs}>${esc(label)}</button>`;

/* The overdue alert names its team by id (details.team, and team_id since this round). */
const coAlertTeam = (a, d) => alertTeam(a, d) || S.teams.find((x) => x.id === d.team) || null;
