  if (Array.isArray(v)) return esc(v.length ? v.map(audPlain).join(', ') : 'none');
  if (k === 'seconds') return esc(dur(+v));
  if (k === 'stall_minutes') return esc(dur(+v * 60));
  const named = AUD_REF.users.get(String(v)) || AUD_REF.prj.get(String(v));
  if (named) return esc(named);
  // A status word such as needs_info reads as words; tool names stay as they are.
  if (k !== 'tool' && /^[a-z]+(_[a-z]+)+$/.test(String(v))) return esc(String(v).replace(/_/g, ' '));
  return refLink(v) ??`<span title="${esc(String(v))}">${esc(trunc(String(v), 90))}</span>`;
