    if (e.target_kind === 'policy' && k === 'rules') { const kk = keyOfPolicy(e.target_id); out.push(['rules', kk ? `<a href="#" data-key="${esc(kk.id)}|rules">${esc(v)} rules</a>` : esc(v)]); continue; }
