    bound_key_elsewhere: ['Bound key used elsewhere', `${who}'s session key is bound to ${d.bound_pc?.name || 'a PC'} but was presented from ${d.used_from_pc?.name || 'an app key with no PC'}. The login was refused. If the key leaked, rotate it.`, [...keyActs()]],
