        await api('/telemetry/baseline', 'PUT', { label: $('#tbL').value.trim() || 'Before the hub', calls_per_cycle: calls, tokens_per_cycle: tok, ...($('#tbN').value.trim() ? { note: $('#tbN').value.trim() } : {}) });
